const src = $json.body ?? $json;
const personalDomains = ['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','proton.me','protonmail.com'];
const email = String(src.email ?? '').trim().toLowerCase();
const domain = email.includes('@') ? email.split('@').pop() : '';

const companySize = Number(src.company_size ?? 0) || 0;
const budgetText = String(src.budget_range ?? '').toLowerCase();
const budgetNums = budgetText.match(/\d+/g)?.map(Number) ?? [];
const budgetMin = budgetNums.length ? Math.min(...budgetNums) : 0;

const timelineText = String(src.timeline ?? '').toLowerCase();
let timelineDays = 999;
if (/0\s*-\s*30|30\s*days|1\s*month/.test(timelineText)) timelineDays = 30;
else if (/30\s*-\s*60|60\s*days|2\s*months?/.test(timelineText)) timelineDays = 60;
else if (/60\s*-\s*90|90\s*days|3\s*months?/.test(timelineText)) timelineDays = 90;
else if (/180|6\s*months?/.test(timelineText)) timelineDays = 180;

const normalized = {
  first_name: String(src.first_name ?? '').trim(),
  last_name: String(src.last_name ?? '').trim(),
  email,
  company: String(src.company ?? '').trim(),
  job_title: String(src.job_title ?? '').trim(),
  company_size: companySize,
  budget_range: String(src.budget_range ?? '').trim(),
  budget_min: budgetMin,
  timeline: String(src.timeline ?? '').trim(),
  timeline_days: timelineDays,
  message: String(src.message ?? '').trim(),
  source: String(src.source ?? 'unknown').trim().toLowerCase(),
  is_business_email: Boolean(domain) && !personalDomains.includes(domain)
};

normalized.validation_errors = [];
if (!normalized.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized.email)) normalized.validation_errors.push('valid email is required');
if (!normalized.message) normalized.validation_errors.push('message is required');
normalized.valid = normalized.validation_errors.length === 0;

return [{ json: normalized }];

const lead = $json;
let score = 0;
const breakdown = {};

const title = lead.job_title.toLowerCase();
if (/(founder|owner|chief|ceo|cto|cmo|coo|vp|vice president|head|director)/.test(title)) breakdown.role = 15;
else if (/(manager|lead)/.test(title)) breakdown.role = 10;
else if (title) breakdown.role = 5;
else breakdown.role = 0;
score += breakdown.role;

if (lead.company_size >= 20 && lead.company_size <= 500) breakdown.company_size = 15;
else if ((lead.company_size >= 5 && lead.company_size < 20) || (lead.company_size > 500 && lead.company_size <= 1000)) breakdown.company_size = 8;
else breakdown.company_size = 0;
score += breakdown.company_size;

breakdown.business_email = lead.is_business_email ? 10 : 0;
score += breakdown.business_email;

if (lead.budget_min >= 5000) breakdown.budget = 15;
else if (lead.budget_min >= 2500) breakdown.budget = 10;
else if (lead.budget_min >= 1000) breakdown.budget = 5;
else breakdown.budget = 0;
score += breakdown.budget;

if (lead.timeline_days <= 30) breakdown.timeline = 15;
else if (lead.timeline_days <= 90) breakdown.timeline = 12;
else if (lead.timeline_days <= 180) breakdown.timeline = 6;
else breakdown.timeline = 0;
score += breakdown.timeline;

if (/(demo|consult|sales)/.test(lead.source)) breakdown.source = 10;
else if (/(website|form|inbound)/.test(lead.source)) breakdown.source = 6;
else breakdown.source = 2;
score += breakdown.source;

return [{ json: { ...lead, deterministic_score: Math.min(score, 80), deterministic_breakdown: breakdown } }];

parameters.text:
=Assess this inbound lead only for semantic fit and intent.

Company: {{ $json.company }}
Role: {{ $json.job_title }}
Message: {{ $json.message }}
Timeline: {{ $json.timeline }}
Source: {{ $json.source }}

Return a fit_score from 0 to 20. Judge problem clarity, urgency, fit for AI/automation services, and buying intent. Do not re-score company size, email type, role seniority, or budget because those are handled separately. Keep the explanation concise.

parameters.jsCode:
const base = $('Deterministic Score').first().json;
const incoming = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const aiScore = Math.max(0, Math.min(20, Number(incoming.fit_score ?? incoming.output?.fit_score ?? 0) || 0));
const finalScore = Math.max(0, Math.min(100, base.deterministic_score + aiScore));

let tier = 'LOW';
if (finalScore >= 80) tier = 'HOT';
else if (finalScore >= 60) tier = 'WARM';
else if (finalScore >= 40) tier = 'NURTURE';

const recommendedAction = tier === 'HOT'
  ? 'Immediate sales review and follow-up draft'
  : tier === 'WARM'
  ? 'Sales follow-up queue and follow-up draft'
  : tier === 'NURTURE'
  ? 'Add to nurture workflow'
  : 'Log for later review';

return [{ json: {
  ...base,
  ai_fit_score: aiScore,
  ai_assessment: incoming,
  lead_score: finalScore,
  tier,
  recommended_action: recommendedAction,
  needs_followup_draft: ['HOT','WARM'].includes(tier)
}}];

