const draft = typeof $json.output === 'string' ? $json.output : ($json.text ?? $json.response ?? JSON.stringify($json.output ?? ''));
return [{ json: {
  ...lead,
  followup_draft: draft,
  approval_status: 'pending_human_approval'
}}];
